const raw = $input.first().json;
// Parsing securise du body — JSON.parse sans try/catch = crash si body non-JSON
let body;
if (raw.body && typeof raw.body === 'object') {
  body = raw.body;
} else if (typeof raw.body === 'string') {
  try {
    body = JSON.parse(raw.body.replace(/^=+/, '').trim());
  } catch(e) {
    body = raw;
  }
} else {
  body = raw;
}

// Les payloads binaires volumineux (ZIP a ameliorer, PDF de specs) ne sont PAS
// propages par la chaine d extraction : Detect Input et Build PDF/DOCX Context
// reconstruisent un objet allege qui les omet. On les relit donc directement
// depuis le Webhook, source de verite du run. Meme pattern que Extract PDF Text.
const _wh = $('Webhook').first().json;
const _whBody = (_wh && _wh.body && typeof _wh.body === 'object') ? _wh.body : (_wh || {});

if (!body.task_id) throw new Error('task_id requis');
return [{ json: {
  task_id:              String(body.task_id),
  userRequest:          String(body.userRequest || ''),
  environment:          String(body.environment || 'staging'),
  language:             String(body.language    || 'javascript'),
  framework:            String(body.framework   || 'express'),
  input_type:           String(body.input_type  || 'direct'),
  improve_mode:         body.improve_mode         || _whBody.improve_mode || false,
  improve_prompt:       body.improve_prompt       || body.userRequest || '',
  existing_zip_base64:  body.existing_zip_base64   || _whBody.existing_zip_base64   || null,
  existing_zip_filename: body.existing_zip_filename || _whBody.existing_zip_filename || null,
  pdf_base64:           body.pdf_base64            || _whBody.pdf_base64 || null,
  pdf_filename:         body.pdf_filename           || _whBody.pdf_filename || null,
  specs_context:        body.specs_context          || null
} }];

const arch    = $input.first().json;
const initial = $('Validate Input').first().json;

// ── Récupérer les artifacts du LLM Architect ──────────────────────────────────
const llmArtifacts = arch.artifacts || arch.architecture || arch.specs || arch.data || arch.result || arch;

// ── Récupérer les invariants déterministes depuis Build Architect Payload ──────
// Ces invariants sont issus du Spec Normalizer — endpoints et stores exacts
let deterministicArtifacts = null;
try {
  deterministicArtifacts = $('Build Architect Payload').first().json._deterministic_artifacts || null;
} catch(e) {}

// ── FUSION : LLM enrichit, Normalizer contraint ───────────────────────────────
// INVARIANTS (Normalizer) : priority_endpoints, stores, data_model
// ENRICHISSEMENTS (LLM)   : mvp_scope, deferred, abuse_cases, project_name, architecture

const finalEndpoints = (deterministicArtifacts && deterministicArtifacts.priority_endpoints &&
                         deterministicArtifacts.priority_endpoints.length > 0)
  ? deterministicArtifacts.priority_endpoints
  : (llmArtifacts.priority_endpoints && llmArtifacts.priority_endpoints.length > 0)
    ? llmArtifacts.priority_endpoints : [];

const finalStores = (deterministicArtifacts && deterministicArtifacts.stores &&
                      Object.keys(deterministicArtifacts.stores).length > 0)
  ? deterministicArtifacts.stores
  : (llmArtifacts.stores && Object.keys(llmArtifacts.stores).length > 0)
    ? llmArtifacts.stores : {};

const finalDataModel = (deterministicArtifacts && deterministicArtifacts.data_model &&
                         Object.keys(deterministicArtifacts.data_model).length > 0)
  ? deterministicArtifacts.data_model
  : (llmArtifacts.data_model && Object.keys(llmArtifacts.data_model).length > 0)
    ? llmArtifacts.data_model : {};

// Enrichissements LLM — avec sanitisation anti-hallucination
// mvp_scope : string max 300 chars
const rawMvpScope = llmArtifacts.mvp_scope;
const finalMvpScope = (typeof rawMvpScope === 'string' && rawMvpScope.length > 0)
  ? rawMvpScope.substring(0, 300)
  : (deterministicArtifacts ? 'MVP ' + deterministicArtifacts.project_name : '');

// deferred : tableau de strings uniquement
const rawDeferred = llmArtifacts.deferred;
const finalDeferred = Array.isArray(rawDeferred)
  ? rawDeferred.map(d => typeof d === 'string' ? d : (d && d.feature ? d.feature : String(d))).filter(d => d.length > 0).slice(0, 10)
  : [];

// abuse_cases : tableau de strings
const rawAbuse = llmArtifacts.abuse_cases;
const finalAbuseCases = Array.isArray(rawAbuse)
  ? rawAbuse.map(a => typeof a === 'string' ? a : (a && a.name ? a.name : String(a))).filter(a => a.length > 0).slice(0, 8)
  : [];

// project_name : string courte sans caractères dangereux
const rawProjectName = llmArtifacts.project_name;
const finalProjectName = (typeof rawProjectName === 'string' && rawProjectName.length > 0 && rawProjectName.length < 50)
  ? rawProjectName.replace(/[<>"'&;]/g, '').trim()
  : (deterministicArtifacts && deterministicArtifacts.project_name) || '';

const mergedArtifacts = {
  stack:       llmArtifacts.stack       || 'Node.js / Express',
  architecture:llmArtifacts.architecture || 'MVC',
  auth:        llmArtifacts.auth         || 'none',
  database:    llmArtifacts.database     || 'none',
  project_name:     finalProjectName,
  mvp_scope:        finalMvpScope,
  priority_endpoints: finalEndpoints,
  data_model:       finalDataModel,
  stores:           finalStores,
  deferred:         finalDeferred,
  abuse_cases:      finalAbuseCases,
  file_manifest:    llmArtifacts.file_manifest || ['server.js','package.json','.env.example','frontend/index.html','frontend/style.css','frontend/app.js']
};

// ── Contexte ZIP si mode amélioration ────────────────────────────────────────
let existingServerJs = '';
let existingRoutes   = [];
let existingStores   = {};
let existingVersion  = '1.0';
try {
  const zipResult = $('Agent ZIP Analyzer').first().json;
  if (zipResult && zipResult.improve_mode) {
    existingServerJs = zipResult.existing_server_js || '';
    existingRoutes   = zipResult.existing_routes    || [];
    existingStores   = zipResult.existing_stores    || {};
    existingVersion  = zipResult.existing_version   || '1.0';
  }
} catch(e) {}

return [{
  json: {
    task_id:            initial.task_id,
    environment:        initial.environment || 'staging',
    userRequest:        (initial.improve_mode && initial.specs_context)
                          ? initial.specs_context : initial.userRequest,
    improve_prompt:     initial.improve_mode ? (initial.improve_prompt || initial.userRequest) : '',
    language:           initial.language,
    framework:          initial.framework,
    improve_mode:       initial.improve_mode || false,
    architecture:       mergedArtifacts,
    priority_endpoints: finalEndpoints,
    mvp_scope:          finalMvpScope,
    project_name:       finalProjectName,
    data_model:         finalDataModel,
    stores:             finalStores,
    existing_server_js: existingServerJs,
    existing_routes:    existingRoutes,
    existing_stores:    existingStores,
    existing_version:   existingVersion,
    backend_instructions: mergedArtifacts.backend_instructions || []
  }
}];

const backend   = $input.first().json;
const initial   = $('Validate Input').first().json;
const artifacts = backend.artifacts || backend.architecture || {};

const stores = (backend.stores && Object.keys(backend.stores).length > 0)
  ? backend.stores
  : (artifacts.stores && Object.keys(artifacts.stores).length > 0) ? artifacts.stores : {};

const dataModel = (backend.data_model && Object.keys(backend.data_model).length > 0)
  ? backend.data_model
  : (artifacts.data_model && Object.keys(artifacts.data_model).length > 0) ? artifacts.data_model : {};

const endpoints = (backend.priority_endpoints && backend.priority_endpoints.length > 0)
  ? backend.priority_endpoints
  : (artifacts.priority_endpoints && artifacts.priority_endpoints.length > 0) ? artifacts.priority_endpoints : [];

// project_name : ordre de priorité
// 1. _deterministic_artifacts (Normalizer + specs_context → toujours correct)
// 2. Build Backend Payload (LLM enrichment)
// 3. backend.project_name / artifacts.project_name (fallbacks)
let projectName = '';
try { projectName = $('Build Architect Payload').first().json._deterministic_artifacts?.project_name || ''; } catch(e) {}
if (!projectName) { try { projectName = $('Build Backend Payload').first().json.project_name || ''; } catch(e) {} }
if (!projectName) { projectName = backend.project_name || artifacts.project_name || ''; }

const mvpScope = backend.mvp_scope || artifacts.mvp_scope
  || (() => { try { return $('Build Backend Payload').first().json.mvp_scope || ''; } catch(e) { return ''; } })()
  || projectName;

return [{ json: {
  task_id:               initial.task_id,
  userRequest:           initial.userRequest,
  improve_mode:          initial.improve_mode || false,
  architecture:          artifacts,
  priority_endpoints:    endpoints,
  mvp_scope:             mvpScope,
  project_name:          projectName,
  data_model:            dataModel,
  stores:                stores,
  frontend_instructions: artifacts.frontend_instructions || []
}}];

