const initial = $('Validate Input').first().json;
const backend = $('Agent Backend').first().json;

// Chercher le vrai package.json généré par le Backend
const pkgFile = (backend.files || []).find(f => f.path === 'package.json');
let packageJson = null;

if (pkgFile && pkgFile.content) {
  try {
    // Nettoyer le commentaire // FILE: package.json
    const cleaned = pkgFile.content.replace(/^\/\/ FILE:.*\n/, '').trim();
    packageJson = JSON.parse(cleaned);
  } catch(e) {
    packageJson = null;
  }
}

// Fallback si pas de package.json valide
if (!packageJson) {
  packageJson = {
    name: 'generated-app',
    version: '1.0.0',
    dependencies: { express: '4.21.2' },
    devDependencies: {}
  };
}

return [{
  json: {
    task_id:      initial.task_id,
    language:     initial.language,
    package_json: packageJson
  }
}];

