const endpoints = artifacts.priority_endpoints || [];

// Construire les vrais endpoints depuis l'Architect
const realEndpoints = endpoints
  .filter(ep => ep.path !== '/health')
  .map(ep => ep.path.replace(/:id/g, '1'));


// Recuperer le server.js genere pour un DAST base sur le vrai code (robuste aux formes)
let _serverJs = '';
try {
  var _bk = $('Agent Backend').first().json || {};
  var _files = _bk.files || (_bk.json && _bk.json.files) || (_bk.data && _bk.data.files) || [];
  if (Array.isArray(_files)) {
    var _sf = _files.find(function(f){ return f && typeof f.path === 'string' && f.path.replace(/^.*\//, '') === 'server.js'; });
    if (_sf) _serverJs = _sf.content || '';
  }
} catch(e) {}

return [{
  json: {
    task_id:     initial.task_id,
    server_js:   _serverJs,
    server_js_len: _serverJs.length,
    environment: initial.environment,
    target_url:  'http://localhost:3000',
    endpoints:   realEndpoints.length ? realEndpoints : ['/health'],
    simulate:    'pass'
  }
}];

