          && !/[:|=\t]/.test(firstLine)
          && firstWords.length <= 2
          && !PREP_FR.includes(lastWord);
        if (isCleanName) pn = firstLine;
      } catch(e) {}
      const endpoints = [{ method: 'GET', path: '/health', description: 'health check' }];
      (norm.routes || []).filter(r => r.path !== '/health').slice(0, 6).forEach(r => {
        endpoints.push({ method: r.method, path: r.path, description: r.description || (r.method + ' ' + r.path) });
      });
      const dataModel = {};
      const stores    = {};
      (norm.resources || []).forEach(res => {
        const fields = Object.assign({ id: 'number', created_at: 'string' }, res.fields || {});
        dataModel[res.name] = fields;
        stores[res.name]    = {
          store_name:     res.name_plural || (res.name + 's'),
          required_fields: (res.required_fields || []).filter(f => !['id','created_at'].includes(f))
        };
      });
      deterministicArtifacts = { project_name: pn, priority_endpoints: endpoints,
        data_model: dataModel, stores: stores };
    }
  } catch(e) {}
}

// ── Toujours envoyer au LLM Architect (même si structured_context valide) ────
// Le LLM enrichit : mvp_scope, deferred, abuse_cases, architecture
// Les invariants (endpoints, stores, data_model) sont protégés par Build Backend Payload
const userRequest = (normData.normalized_userRequest && normData.normalized_userRequest.length > 20)
  ? normData.normalized_userRequest
  : (initial.specs_context || initial.userRequest);

return [{ json: {
  _deterministic_architect:  false,  // toujours LLM
  _deterministic_artifacts:  deterministicArtifacts,  // invariants pour Build Backend
  task_id:           initial.task_id,
  userRequest:       userRequest,
  structured_context: sc,
  specs_context:     initial.specs_context || initial.userRequest,
  project_name:      normData.project_name || '',
  language:          initial.language    || 'javascript',
  framework:         initial.framework   || 'express',
  environment:       initial.environment || 'staging',
  improve_mode:      initial.improve_mode || false,
  improve_prompt:    initial.improve_mode ? (initial.improve_prompt || initial.userRequest) : '',
  existing_routes:   initial.existing_routes  || [],
  existing_stores:   initial.existing_stores  || {},
  existing_version:  initial.existing_version || '1.0',
  next_version:      initial.next_version     || '1.1',
  changelog_context: initial.changelog_context || '',
  backend_instructions:  initial.backend_instructions  || [],
  frontend_instructions: initial.frontend_instructions || []
}}];
